	(270,1,'POST','底部导航编辑','192.168.100.225','/api/decorate/tabbar/save','com.mdd.admin.controller.decorate.DecorateTabbarController.save()','[{\"list\":[{\"createTime\":\"2024-05-01 12:54:18\",\"id\":37,\"link\":{\"path\":\"/pages/index/index\",\"name\":\"商城首页\",\"type\":\"shop\"},\"name\":\"首页\",\"selected\":\"http://192.168.100.169:8083/api/uploads/image/20240501/96146426-84f9-43c7-9dfb-ec03dcf51028.png\",\"unselected\":\"http://192.168.100.169:8083/api/uploads/image/20240501/798caac1-9e0d-4e7d-b404-ce41d96dbb8e.png\",\"updateTime\":\"2024-05-01 12:54:18\"},{\"createTime\":\"2024-05-01 12:54:18\",\"id\":38,\"link\":{\"path\":\"/pages/news/news\",\"name\":\"学习手册\",\"type\":\"shop\"},\"name\":\"学习中心\",\"selected\":\"http://192.168.100.169:8083/api/uploads/image/20240501/ef0d2053-bbf6-42ef-922e-d1db92bef6eb.png\",\"unselected\":\"http://192.168.100.169:8083/api/uploads/image/20240501/667f31f7-3f86-4bb3-8e10-b6af4f81f2f0.png\",\"updateTime\":\"2024-05-01 12:54:18\"},{\"createTime\":\"2024-05-01 12:54:18\",\"id\":39,\"link\":{\"path\":\"/packages/pages/audio_list/audio_list\",\"name\":\"有声读物\",\"type\":\"shop\"},\"name\":\"有声读物\",\"selected\":\"http://192.168.100.169:8083/api/uploads/image/20240501/858297f3-7d43-4bd7-b22a-01ac91f01e9f.png\",\"unselected\":\"http://192.168.100.169:8083/api/uploads/image/20240501/ed8aff54-975b-4eac-8542-5ee0bad305ce.png\",\"updateTime\":\"2024-05-01 12:54:18\"},{\"createTime\":\"2024-05-01 12:54:18\",\"id\":40,\"link\":{\"path\":\"/packages/pages/classroom/classroom\",\"name\":\"网上课堂\",\"type\":\"shop\"},\"name\":\"网上课堂\",\"selected\":\"http://192.168.100.169:8083/api/uploads/image/20240501/718b0f33-ebaf-4032-a278-254e070b3e97.png\",\"unselected\":\"http://192.168.100.169:8083/api/uploads/image/20240501/210807e8-3f68-4c04-81e1-d653a1bf5c9c.png\",\"updateTime\":\"2024-05-01 12:54:18\"},{\"createTime\":\"2024-05-01 12:54:18\",\"id\":41,\"link\":{\"path\":\"/pages/user/user\",\"name\":\"个人中心\",\"type\":\"shop\"},\"name\":\"我的\",\"selected\":\