	(320,1,'POST','页面装修保存','36.100.8.248','/api/decorate/pages/save','com.mdd.admin.controller.decorate.DecoratePagesController.save()','[{\"id\":1,\"pageData\":\"[{\\\"title\\\":\\\"搜索\\\",\\\"name\\\":\\\"search\\\",\\\"disabled\\\":1,\\\"content\\\":{},\\\"styles\\\":{}},{\\\"title\\\":\\\"首页轮播图\\\",\\\"name\\\":\\\"banner\\\",\\\"content\\\":{\\\"enabled\\\":1,\\\"data\\\":[{\\\"image\\\":\\\"/api/static/banner01.png\\\",\\\"name\\\":\\\"\\\",\\\"link\\\":{\\\"path\\\":\\\"/pages/index/index\\\",\\\"name\\\":\\\"商城首页\\\",\\\"type\\\":\\\"shop\\\"}},{\\\"image\\\":\\\"/api/static/banner02.png\\\",\\\"name\\\":\\\"\\\",\\\"link\\\":{}}]},\\\"styles\\\":{}},{\\\"title\\\":\\\"导航菜单\\\",\\\"name\\\":\\\"nav\\\",\\\"content\\\":{\\\"enabled\\\":1,\\\"data\\\":[{\\\"image\\\":\\\"/api/static/nav01.png\\\",\\\"name\\\":\\\"积分记录\\\",\\\"link\\\":{\\\"path\\\":\\\"/packages/pages/integral_log/integral_log\\\",\\\"name\\\":\\\"积分记录\\\",\\\"type\\\":\\\"shop\\\"}},{\\\"image\\\":\\\"/api/static/nav02.png\\\",\\\"name\\\":\\\"积分商城\\\",\\\"link\\\":{\\\"path\\\":\\\"/packages/pages/integral_shop/integral_shop\\\",\\\"name\\\":\\\"积分商城\\\",\\\"type\\\":\\\"shop\\\"}},{\\\"image\\\":\\\"/api/static/nav03.png\\\",\\\"name\\\":\\\"积分兑换\\\",\\\"link\\\":{\\\"path\\\":\\\"/packages/pages/integral_shop_order/integral_shop_order\\\",\\\"name\\\":\\\"积分兑换订单\\\",\\\"type\\\":\\\"shop\\\"}},{\\\"image\\\":\\\"/api/static/nav04.png\\\",\\\"name\\\":\\\"党费缴纳\\\",\\\"link\\\":{\\\"path\\\":\\\"/packages/pages/party_fee/party_fee\\\",\\\"name\\\":\\\"党费缴纳\\\",\\\"type\\\":\\\"shop\\\"}},{\\\"image\\\":\\\"/api/static/nav05.png\\\",\\\"name\\\":\\\"答题记录\\\",\\\"link\\\":{\\\"path\\\":\\\"/packages/pages/answer_log/answer_log\\\",\\\"name\\\":\\\"答题记录\\\",\\\"type\\\":\\\"shop\\\"}},{\\\"image\\\":\\\"api/uploads/image/20240502/2542e5ef-a59c-4265-8552-1cf8a599c678.png\\\",\\\"name\\\":\\\"党员风采\\\",\\\"link\\\":{\\\"path\\\":\\\"/packages/pages/member_list/member_list\\\",\\\"name\\\":\\\"党员风采\\\",\\\"type\\\":\\\"shop\\\"}},{\\\"image\\\":\\\"api/uploads/image/20240502/6728975a-c275-447b-890d-db97911ba936.png\\\",\\\"name\\\":\\\"我的收藏\\\",\\\"link\\\":{\\\"path\\\":\\\"/pages/collection/collection\\\",\\\"name\\\":\\\"我的收藏\\\",\\\"type\\\":\\\"shop\\\"}},{\\\"image\\\":\\\"api/uploads/image/20240502/beee8615-eebe-49a8-8e54-357c76bf25d9.png\\\",\\\"name\\\":\\\"积分订单\\\",\\\"link\\\":{\\\"path\\\":\\\"/packages/pages/integral_shop_order/integral_shop_order\\\",\\\"name\\\":\\\"积分兑换订单\\\",\\\"type\\\":\\\"shop\\\"}},{\\\"image\\\":\\\"api/uploads/image/20240502/6b9257d2-1f96-4a0b-aa06-b849811673e0.png\\\",\\\"name\\\":\\\"问卷调查\\\",\\\"link\\\":{\\\"path\\\":\\\"/packages/pages/questionnaire_list/questionnaire_list\\\",\\\"name\\\":\\\"问卷调查\\\",\\\"type\\\":\\\"shop\\\"}},{\\\"image\\\":\\\"api/uploads/image/20240502/bef051f6-6ea9-4788-b08f-2d4fa395ae6a.png\\\",\\\"name\\\":\\\"党史答题\\\",\\\"link\\\":{\\\"path\\\":\\\"/packages/pages/answer/answer\\\",\\\"name\\\":\\\"党史答题\\\",\\\"type\\\":\\\"shop\\\"}}]},\\\"styles\\\":{}},{\\\"title\\\":\\\"首页滚动通知\\\",\\\"name\\\":\\\"notice\\\",\\\"content\\\":{\\\"enabled\\\":1,\\\"icon\\\":\\\"api/uploads/image/20240328/9e3c7cbf-9657-4e01-b9ce-19327b90862b.png\\\",\\\"data\\\":[{\\\"text\\\":\\\"我希望五十年以后，你还在我左右，感受那夕阳的温柔，\\\"},{\\\"text\\\":\\\"那片沼泽地\\\"},{\\\"text\\\":\\\"我要什么自行车\\\"}]},\\\"styles\\\":{}},{\\\"id\\\":\\\"l84almsk2uhyf\\\",\\\"title\\\":\\\"资讯\\\",\\\"name\\\":\\\"news\\\",\\\"disabled\\\":1,\\\"content\\\":{},\\\"styles\\\":{}}]\"}]','',1,1714632940,1714632940,11,1714632940),
